import re
lines=open('specs/sk-doc/066-skill-readability-refinement/008-sk-doc/008-sk-create-frontmatter/scratch/inbound-anchors.txt').read().splitlines()
for l in lines:
    f, rest = l.split(': ',1)
    print('=====',f)
    for ref in re.findall(r'([\w./-]+\.md):(\d+)', rest):
        path,n=ref
        print(f'  {path}:{n}')
        try:
            ls=open(path).read().splitlines()
            for i in range(max(0,int(n)-3), min(len(ls), int(n)+2)):
                print(f'    {i+1}: {ls[i]}')
        except FileNotFoundError:
            print('    MISSING')
EOF

